import{_ as s,y as i,a as c,o as h,a2 as n,D as a,g as e,I as o}from"./chunks/framework.DCcmcJcL.js";const k=JSON.parse('{"title":"Checkout","description":"","frontmatter":{},"headers":[],"relativePath":"configure/checkout.md","filePath":"configure/checkout.md","lastUpdated":1789441803000}'),d={name:"configure/checkout.md"};function u(g,t,l,p,f,m){const r=i("ImagePopup");return h(),c("div",null,[t[0]||(t[0]=n('<h1 id="checkout" tabindex="-1">Checkout <a class="header-anchor" href="#checkout" aria-label="Permalink to &quot;Checkout&quot;">​</a></h1><p>The <strong>Checkout</strong> screen decides whether shoppers can buy at all, whether guests can check out, what the cart page offers, and how the mini cart behaves. These settings apply to the whole store.</p><h2 id="shopping-cart" tabindex="-1">Shopping cart <a class="header-anchor" href="#shopping-cart" aria-label="Permalink to &quot;Shopping cart&quot;">​</a></h2><ol><li>Go to <strong>Configure &gt;&gt; Sales &gt;&gt; Checkout</strong>.</li><li>In <strong>Shopping Cart</strong>, switch each setting described below on or off.</li><li>Click <strong>Save Configuration</strong>.</li></ol>',4)),a(r,{src:"/images/configure/checkout-settings.png",alt:"Shopping Cart and Mini Cart sections of the Checkout screen"}),t[1]||(t[1]=n('<p>All four settings are on in a new store.</p><table tabindex="0"><thead><tr><th>Setting</th><th>What it does</th></tr></thead><tbody><tr><td><strong>Cart Page</strong></td><td>Turns buying on or off for the whole storefront. When it&#39;s off, the store works as a catalog: <strong>Add To Cart</strong>, <strong>Buy Now</strong> and the cart icon are hidden, product pages show a <strong>Contact Us</strong> button that opens a contact form, products can&#39;t be moved from the <a href="./../customer/customer-account.html#wishlist">wishlist</a> to the cart, and the cart and checkout pages can&#39;t be opened.</td></tr><tr><td><strong>Allow guest checkout</strong></td><td>Lets shoppers place an order without signing in. When it&#39;s off, shoppers who go to checkout are sent to sign in first, and return to checkout afterwards.</td></tr><tr><td><strong>Cross sell Products</strong></td><td>Shows cross-sell products on the cart page. How many are shown is set under <a href="./cart-view-page.html">Cart View Page</a>.</td></tr><tr><td><strong>Estimated Shipping</strong></td><td>Shows <strong>Estimate Shipping and Tax</strong> on the cart page, where shoppers enter their destination to see the shipping and tax before checkout.</td></tr></tbody></table><h3 id="require-an-account-for-particular-products" tabindex="-1">Require an account for particular products <a class="header-anchor" href="#require-an-account-for-particular-products" aria-label="Permalink to &quot;Require an account for particular products&quot;">​</a></h3><p>While <strong>Allow guest checkout</strong> is on, you can still require an account for particular products:</p><ol><li>Go to <strong>Catalog &gt;&gt; Products</strong>.</li><li>Open the product.</li><li>Switch <strong>Guest Checkout</strong> off.</li><li>Click <strong>Save Product</strong>.</li></ol><p>When the cart holds such a product, or any downloadable product, guests are sent to sign in before checkout. The product&#39;s <strong>Guest Checkout</strong> field is described in <a href="./../product-types/products.html#shipping-and-settings">Products</a>.</p><h2 id="mini-cart" tabindex="-1">Mini cart <a class="header-anchor" href="#mini-cart" aria-label="Permalink to &quot;Mini cart&quot;">​</a></h2><p>The mini cart is the drawer that opens from the cart icon in the storefront header.</p><ol><li>Go to <strong>Configure &gt;&gt; Sales &gt;&gt; Checkout</strong>.</li><li>In <strong>Mini Cart</strong>, set the options described below.</li><li>Click <strong>Save Configuration</strong>.</li></ol><table tabindex="0"><thead><tr><th>Setting</th><th>What it does</th></tr></thead><tbody><tr><td><strong>Display Mini Cart</strong></td><td>Opens the mini cart when shoppers click the cart icon. When it&#39;s off, the cart icon takes shoppers straight to checkout. It&#39;s on in a new store.</td></tr><tr><td><strong>Summary</strong></td><td>What the number on the cart icon counts. <strong>Display number of items in cart</strong>, the default, counts the different items in the cart. <strong>Display item quantities</strong> counts the total quantity, so two units of one product count as two. It applies only while <strong>Display Mini Cart</strong> is on; while it&#39;s off, the number counts the total quantity.</td></tr><tr><td><strong>Mini Cart Offer Information</strong></td><td>A line of text under the mini cart&#39;s heading, such as a promotion. Up to 200 characters. The default is <code>Get Up To 30% OFF on your 1st order</code>.</td></tr></tbody></table>',10)),a(r,{src:"/images/configure/checkout-mini-cart-storefront.png",alt:"Mini cart on the storefront with the offer text under its heading"}),t[2]||(t[2]=e("h2",{id:"differences-in-bagisto-2-4",tabindex:"-1"},[o("Differences in Bagisto 2.4 "),e("a",{class:"header-anchor",href:"#differences-in-bagisto-2-4","aria-label":'Permalink to "Differences in Bagisto 2.4"'},"​")],-1)),t[3]||(t[3]=e("p",null,[o("In Bagisto 2.4, "),e("strong",null,"Summary"),o(" is in its own "),e("strong",null,"My Cart"),o(" section on this screen.")],-1))])}const w=s(d,[["render",u]]);export{k as __pageData,w as default};
